#!/usr/bin/env zsh
# ==============================================================================
# OctoBara - The Zen Multi-tasking Architect Terminal MOTD
# ==============================================================================

# ANSI Color Definitions
BOLD="\033[1m"
DIM="\033[2m"
RESET="\033[0m"
ORANGE="\033[38;2;247;139;38m"
GREEN="\033[38;2;157;190;101m"
BLUE="\033[38;2;79;140;201m"
PURPLE="\033[38;2;177;128;215m"
CYAN="\033[38;2;86;212;221m"
GRAY="\033[38;2;139;148;158m"

# System Information
USER_NAME="$(whoami)"
HOST_NAME="$(hostname -s)"
OS_NAME="$(sw_vers -productName 2>/dev/null || uname -s) $(sw_vers -productVersion 2>/dev/null || uname -r)"
SHELL_NAME="${SHELL:t}"
UPTIME_STR="$(uptime | sed 's/.*up \([^,]*\), .*/\1/')"

# Git branch detection
GIT_BRANCH=""
if git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
    GIT_BRANCH="$(git branch --show-current 2>/dev/null)"
fi

# Random Zen Architect Quotes
QUOTES=(
    "生产报警心如水，触手并发稳如龟。"
    "架构之道，不在于冗余之复杂，而在于边界之清晰。"
    "写最少的代码，做最稳的并发，顶最大的橘子。"
    "高内聚，低耦合，万物皆空，心如止水。"
    "多线程可以并发，情绪绝对单线程稳定。"
    "没有解决不了的死锁，如果有，就先喝杯热茶。"
    "今日无 Bug，微服务皆安，准点下班！"
)
RANDOM_QUOTE="${QUOTES[$((RANDOM % ${#QUOTES[@]} + 1))]}"

